package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import org.junit.Test;

public class ReviewProbe1Test {
    // A first status line of exactly MAX_HEAD_BYTES bytes plus CRLF that is also not a status line.
    // Pre-refactor (344d39e): read -> charge -> status(): cause "the status line and headers exceed 65536 bytes".
    @Test
    public void oversizedMalformedStatusLineKeepsTheBoundCause() throws Exception {
        byte[] line = new byte[ResponseParser.MAX_HEAD_BYTES + 2];
        Arrays.fill(line, (byte) 'X');
        line[line.length - 2] = '\r';
        line[line.length - 1] = '\n';
        try {
            ResponseParser.read(new ByteArrayInputStream(line));
            fail("expected INVALID_RESPONSE");
        } catch (ProxyException e) {
            assertEquals(ProxyException.Kind.INVALID_RESPONSE, e.kind());
            assertEquals("the status line and headers exceed 65536 bytes", e.getCause().getMessage());
        }
    }

    // Second status line after a 1xx head, malformed and over the remaining bound.
    @Test
    public void oversizedMalformedSecondStatusLineKeepsTheBoundCause() throws Exception {
        String interim = "HTTP/1.1 100 Continue\r\n\r\n";
        int remaining = ResponseParser.MAX_HEAD_BYTES - (interim.length());
        StringBuilder sb = new StringBuilder(interim);
        for (int i = 0; i < remaining; i++) sb.append('Y');
        sb.append("\r\n");
        try {
            ResponseParser.read(new ByteArrayInputStream(sb.toString().getBytes(StandardCharsets.ISO_8859_1)));
            fail("expected INVALID_RESPONSE");
        } catch (ProxyException e) {
            assertEquals(ProxyException.Kind.INVALID_RESPONSE, e.kind());
            assertEquals("the status line and headers exceed 65536 bytes", e.getCause().getMessage());
        }
    }
}

